import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Bounded Java task control-plane state machine.
 * Single bounded in-memory authority, NOT a distributed database or execution sandbox.
 * Authenticated tenant/worker and trusted authority time are supplied by the adapter.
 * Reconciliation evidence must come from an authenticated supervisor, not the submitting user.
 */
public final class ScriptControl {
    public enum State { QUEUED, RUNNING, UNKNOWN, CANCEL_REQUESTED, CANCELLED, SUCCEEDED, FAILED }
    public enum Decision { NOT_STARTED_AND_CANNOT_START, SUCCEEDED, FAILED }
    public record Key(String tenant, String request) {}
    public record Input(Key key, String scriptSha, long deadline) {}
    public record Job(Input input, State state, String owner, long epoch, long leaseUntil, String output) {}
    private final Map<Key,Job> jobs = new HashMap<>();
    private final int capacity;
    public ScriptControl(int capacity) {
        if(capacity<=0) throw new IllegalArgumentException("positive capacity required");
        this.capacity=capacity;
    }
    private static void identifier(String s) {
        if(s==null||!s.matches("[A-Za-z0-9_-]{1,64}")) throw new IllegalArgumentException("identifier");
    }
    private static void time(long now) {if(now<0)throw new IllegalArgumentException("trusted nonnegative time");}
    private static void output(String output) {
        if(output==null||output.getBytes(StandardCharsets.UTF_8).length>4096)throw new IllegalArgumentException("output byte limit");
    }
    private Job require(Key key) {
        Job j=jobs.get(key);if(j==null)throw new IllegalStateException("missing job");return j;
    }
    private Job replace(Job j,State state,String owner,long epoch,long until,String output) {
        Job n=new Job(j.input(),state,owner,epoch,until,output);jobs.put(j.input().key(),n);return n;
    }
    public synchronized Job submit(Input in,long now) {
        Objects.requireNonNull(in);Objects.requireNonNull(in.key());time(now);
        identifier(in.key().tenant());identifier(in.key().request());
        if(in.scriptSha()==null||!in.scriptSha().matches("[a-f0-9]{64}")||in.deadline()<=0)
            throw new IllegalArgumentException("input");
        Job old=jobs.get(in.key());
        if(old!=null) {if(!old.input().equals(in))throw new IllegalArgumentException("payload conflict");return old;}
        if(in.deadline()<=now)throw new IllegalStateException("expired input");
        if(jobs.size()>=capacity)throw new IllegalStateException("capacity");
        Job j=new Job(in,State.QUEUED,null,0,0,"");jobs.put(in.key(),j);return j;
    }
    public synchronized Job claim(Key key,String owner,long now,long ttl) {
        identifier(owner);time(now);if(ttl<=0)throw new IllegalArgumentException("ttl");
        long until=Math.addExact(now,ttl);Job j=require(key);
        if(j.state()!=State.QUEUED||now>=j.input().deadline())throw new IllegalStateException("not claimable");
        return replace(j,State.RUNNING,owner,Math.incrementExact(j.epoch()),Math.min(until,j.input().deadline()),"");
    }
    public synchronized Job complete(Key key,String owner,long epoch,long now,String receipt) {
        time(now);output(receipt);Job j=require(key);
        if(!Objects.equals(j.owner(),owner)||j.epoch()!=epoch)throw new IllegalStateException("stale owner/epoch");
        if(j.state()==State.SUCCEEDED) {
            if(!j.output().equals(receipt))throw new IllegalArgumentException("receipt conflict");return j;
        }
        if(j.state()!=State.RUNNING||now>=j.leaseUntil())throw new IllegalStateException("not current running lease");
        return replace(j,State.SUCCEEDED,owner,epoch,j.leaseUntil(),receipt);
    }
    public synchronized void expire(long now) {
        time(now);
        for(Job j:List.copyOf(jobs.values()))
            if(j.state()==State.RUNNING&&now>=j.leaseUntil())
                replace(j,State.UNKNOWN,j.owner(),j.epoch(),j.leaseUntil(),j.output());
    }
    public synchronized Job cancel(Key key) {
        Job j=require(key);
        State next=switch(j.state()) {
            case QUEUED -> State.CANCELLED;
            case RUNNING,UNKNOWN -> State.CANCEL_REQUESTED;
            case CANCELLED,CANCEL_REQUESTED -> j.state();
            default -> throw new IllegalStateException("already terminal");
        };
        return replace(j,next,j.owner(),j.epoch(),j.leaseUntil(),j.output());
    }
    /** NOT_STARTED_AND_CANNOT_START requires proof old launch requests can never execute later. */
    public synchronized Job reconcile(Key key,long epoch,Decision decision,String receipt,long now) {
        time(now);output(receipt);Objects.requireNonNull(decision);Job j=require(key);
        if(j.epoch()!=epoch||(j.state()!=State.UNKNOWN&&j.state()!=State.CANCEL_REQUESTED))
            throw new IllegalStateException("stale reconciliation");
        State next=switch(decision) {
            case SUCCEEDED -> State.SUCCEEDED;
            case FAILED -> State.FAILED;
            case NOT_STARTED_AND_CANNOT_START -> j.state()==State.CANCEL_REQUESTED ? State.CANCELLED :
                now>=j.input().deadline() ? State.FAILED : State.QUEUED;
        };
        return replace(j,next,j.owner(),j.epoch(),j.leaseUntil(),receipt);
    }
    public synchronized Job get(Key key) {return require(key);}
    private static void check(boolean b) {if(!b)throw new AssertionError();}
    private static void rejects(Runnable f) {try{f.run();throw new AssertionError("expected rejection");}catch(IllegalArgumentException|IllegalStateException|ArithmeticException expected){}}
    public static void main(String[] args)throws Exception {
        Key key=new Key("tenant","request");Input input=new Input(key,"a".repeat(64),100);
        ScriptControl s=new ScriptControl(10);s.submit(input,0);check(s.submit(input,100).input().equals(input));
        rejects(()->s.submit(new Input(key,"b".repeat(64),100),0));
        try(var pool=Executors.newFixedThreadPool(10)) {
            List<Callable<Boolean>> tasks=new ArrayList<>();
            for(int i=0;i<30;i++)tasks.add(()->{try{s.claim(key,"worker",0,10);return true;}catch(IllegalStateException e){return false;}});
            int wins=0;for(Future<Boolean> f:pool.invokeAll(tasks))if(f.get())wins++;check(wins==1);
        }
        Job j=s.get(key);rejects(()->s.complete(key,"wrong",j.epoch(),1,"x"));
        s.expire(10);check(s.get(key).state()==State.UNKNOWN);
        rejects(()->s.claim(key,"new",10,10));rejects(()->s.complete(key,"worker",j.epoch(),10,"x"));
        s.reconcile(key,j.epoch(),Decision.NOT_STARTED_AND_CANNOT_START,"",10);
        Job next=s.claim(key,"new",10,10);check(next.epoch()==j.epoch()+1);
        rejects(()->s.complete(key,"worker",j.epoch(),11,"x"));
        s.complete(key,"new",next.epoch(),11,"ok");check(s.complete(key,"new",next.epoch(),200,"ok").state()==State.SUCCEEDED);
        rejects(()->s.complete(key,"new",next.epoch(),12,"different"));
        ScriptControl cancel=new ScriptControl(1);cancel.submit(input,0);Job run=cancel.claim(key,"w",0,10);
        check(cancel.cancel(key).state()==State.CANCEL_REQUESTED);rejects(()->cancel.complete(key,"w",run.epoch(),1,"done"));
        check(cancel.reconcile(key,run.epoch(),Decision.SUCCEEDED,"committed",2).state()==State.SUCCEEDED);
        rejects(()->cancel.submit(new Input(new Key("tenant","other"),"a".repeat(64),100),0));
        ScriptControl queued=new ScriptControl(1);queued.submit(input,0);check(queued.cancel(key).state()==State.CANCELLED);
        rejects(()->queued.claim(key,"w",1,1));rejects(()->queued.submit(input,-1));
        ScriptControl bounds=new ScriptControl(1);bounds.submit(input,0);Job b=bounds.claim(key,"w",0,Long.MAX_VALUE);
        check(b.leaseUntil()==100);rejects(()->bounds.complete(key,"w",b.epoch(),1,"中".repeat(1366)));
        bounds.expire(100);check(bounds.reconcile(key,b.epoch(),Decision.NOT_STARTED_AND_CANNOT_START,"",100).state()==State.FAILED);
        System.out.println("PASS ScriptControl: 30 racing claims yield one, payload/receipt conflict, exact expiry UNKNOWN, no blind retry, verified requeue advances epoch, stale completion rejected, cancel can reconcile to success, bounds/deadline/UTF8 output; in-memory control plane only.");
    }
}

import java.io.*;
import java.math.BigDecimal;
import java.nio.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;

/** Dependency-free, bounded teaching parser. JSON null is Java null. */
public final class StrictJson {
    public static final int MAX_BYTES=1_048_576, MAX_DEPTH=64, MAX_NODES=50_000;
    private final String text;
    private int pos, nodes;
    private StrictJson(String text) { this.text=text; }
    public static Object parse(String text) {
        Objects.requireNonNull(text);
        if(text.length()>MAX_BYTES || text.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)
            throw new IllegalArgumentException("JSON byte limit");
        StrictJson p=new StrictJson(text); Object result=p.value(0); p.ws();
        if(p.pos!=text.length()) throw p.bad("trailing input");
        return result;
    }
    public static Object read(Path file) throws IOException {
        try(InputStream in=Files.newInputStream(file)) { return decode(in.readNBytes(MAX_BYTES+1)); }
    }
    public static Object decode(byte[] bytes) throws CharacterCodingException {
        if(bytes.length>MAX_BYTES) throw new IllegalArgumentException("JSON byte limit");
        return parse(StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString());
    }
    private IllegalArgumentException bad(String message) { return new IllegalArgumentException(message+" at "+pos); }
    private void ws() { while(pos<text.length() && " \t\r\n".indexOf(text.charAt(pos))>=0) pos++; }
    private boolean eat(char c) { ws(); if(pos<text.length()&&text.charAt(pos)==c){pos++;return true;}return false; }
    private void need(char c) { if(!eat(c)) throw bad("expected "+c); }
    private Object value(int depth) {
        ws(); if(depth>MAX_DEPTH || ++nodes>MAX_NODES) throw bad("structure limit");
        if(pos>=text.length()) throw bad("missing value");
        char c=text.charAt(pos);
        if(c=='"') return string();
        if(c=='{') {
            pos++; Map<String,Object> map=new TreeMap<>(); if(eat('}'))return map;
            do { ws(); if(pos>=text.length()||text.charAt(pos)!='"')throw bad("object key");
                String key=string(); need(':'); Object v=value(depth+1);
                if(map.containsKey(key))throw bad("duplicate key"); map.put(key,v);
            } while(eat(',')); need('}'); return map;
        }
        if(c=='[') {
            pos++; List<Object> list=new ArrayList<>(); if(eat(']'))return list;
            do { list.add(value(depth+1)); }while(eat(','));need(']');return list;
        }
        for(String token:List.of("true","false","null")) {
            if(text.startsWith(token,pos)) {pos+=token.length();return token.equals("null")?null:token.equals("true");}
        }
        int start=pos;
        if(c=='-')pos++;
        if(pos>=text.length())throw bad("number");
        if(text.charAt(pos)=='0')pos++;
        else { if(!digit19(text.charAt(pos)))throw bad("value"); while(pos<text.length()&&digit(text.charAt(pos)))pos++; }
        if(pos<text.length()&&text.charAt(pos)=='.') {pos++;int before=pos;while(pos<text.length()&&digit(text.charAt(pos)))pos++;if(pos==before)throw bad("fraction");}
        if(pos<text.length()&&(text.charAt(pos)=='e'||text.charAt(pos)=='E')) {
            pos++; if(pos<text.length()&&(text.charAt(pos)=='+'||text.charAt(pos)=='-'))pos++;
            int before=pos;while(pos<text.length()&&digit(text.charAt(pos)))pos++;
            if(pos==before)throw bad("exponent");
        }
        String token=text.substring(start,pos);
        if(token.length()>128)throw bad("number length");
        try { BigDecimal n=new BigDecimal(token); if(Math.abs((long)n.scale())>1000)throw bad("number scale");return n; }
        catch(NumberFormatException e){throw bad("number range");}
    }
    private static boolean digit(char c){return c>='0'&&c<='9';}
    private static boolean digit19(char c){return c>='1'&&c<='9';}
    private char hex() {
        if(pos+4>text.length())throw bad("unicode escape");int n=0;
        for(int i=0;i<4;i++){char h=text.charAt(pos++);int x=h>='0'&&h<='9'?h-'0':h>='a'&&h<='f'?h-'a'+10:h>='A'&&h<='F'?h-'A'+10:-1;if(x<0)throw bad("unicode escape");n=n*16+x;}
        return (char)n;
    }
    private String string() {
        pos++; StringBuilder out=new StringBuilder(); boolean closed=false;
        while(pos<text.length()) {
            char c=text.charAt(pos++);
            if(c=='"'){closed=true;break;} if(c<32)throw bad("control character");
            if(c=='\\') {
                if(pos==text.length())throw bad("escape");char e=text.charAt(pos++);
                c=switch(e){case '"','\\','/'->e;case 'b'->'\b';case 'f'->'\f';case 'n'->'\n';case 'r'->'\r';case 't'->'\t';case 'u'->hex();default->throw bad("escape");};
            }
            out.append(c);
        }
        if(!closed)throw bad("unclosed string");
        for(int i=0;i<out.length();i++) {
            char c=out.charAt(i);
            if(Character.isHighSurrogate(c)) {if(i+1>=out.length()||!Character.isLowSurrogate(out.charAt(++i)))throw bad("unpaired surrogate");}
            else if(Character.isLowSurrogate(c))throw bad("unpaired surrogate");
        }
        return out.toString();
    }
    public static String write(Object value) {
        if(value==null)return "null";
        if(value instanceof String s) {
            StringBuilder b=new StringBuilder("\"");
            for(int i=0;i<s.length();i++) {
                char c=s.charAt(i);
                switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");
                    default->{if(c<32||Character.isSurrogate(c))b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}}
            }
            return b.append('"').toString();
        }
        if(value instanceof BigDecimal n)return n.signum()==0?"0":n.stripTrailingZeros().toString();
        if(value instanceof Boolean||value instanceof Integer||value instanceof Long)return value.toString();
        if(value instanceof List<?> list){List<String> out=new ArrayList<>();for(Object x:list)out.add(write(x));return "["+String.join(",",out)+"]";}
        if(value instanceof Map<?,?> map){TreeMap<String,Object> sorted=new TreeMap<>();for(var e:map.entrySet())sorted.put((String)e.getKey(),e.getValue());List<String> out=new ArrayList<>();for(var e:sorted.entrySet())out.add(write(e.getKey())+":"+write(e.getValue()));return "{"+String.join(",",out)+"}";}
        throw new IllegalArgumentException("unsupported JSON value");
    }
    public static Map<String,Object> object(Object x){if(!(x instanceof Map<?,?> m))throw new IllegalArgumentException("object required");Map<String,Object> r=new TreeMap<>();for(var e:m.entrySet())r.put((String)e.getKey(),e.getValue());return r;}
    public static String str(Map<String,Object> m,String k){if(!(m.get(k) instanceof String s))throw new IllegalArgumentException("string required: "+k);return s;}
    public static long integer(Map<String,Object> m,String k){try{return ((BigDecimal)m.get(k)).longValueExact();}catch(RuntimeException e){throw new IllegalArgumentException("integer required: "+k);}}
    public static void fields(Map<String,Object> m,String... keys){if(!m.keySet().equals(Set.of(keys)))throw new IllegalArgumentException("fields mismatch");}
    public static String id(String s){if(s==null||!s.matches("[A-Za-z0-9_-]{1,64}"))throw new IllegalArgumentException("identifier");return s;}
}

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

/** One cooperating writer; local process restart, not replicated or power-loss durable storage. */
public final class DurableFile implements AutoCloseable {
    @FunctionalInterface interface Cleanup {void run()throws IOException;}
    static void cleanup(Throwable primary,Cleanup action)throws IOException {
        try{action.run();}catch(IOException|RuntimeException|Error secondary){
            if(primary==null)throw secondary;
            if(primary!=secondary)primary.addSuppressed(secondary);
        }
    }
    // This standalone program loads this class once. All cooperating opens use this registry.
    // Never open a second channel first: closing it can release another channel's OS lock.
    private static final Object REGISTRY_LOCK=new Object();
    private static final Set<Lease> ACTIVE=Collections.newSetFromMap(new IdentityHashMap<>());
    private record Lease(Path file,Path lockFile,FileChannel channel,FileLock lock) {}
    private final Path file;
    private final Lease lease;
    private boolean poisoned,closed;

    private static boolean regularOrMissing(Path path)throws IOException {
        try {
            if(!Files.readAttributes(path,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS).isRegularFile())
                throw new IOException("store and lock must be regular files, not symbolic links");
            return true;
        }catch(NoSuchFileException absent){return false;}
    }
    private static boolean sameExisting(Path a,Path b)throws IOException {
        // Attribute reads do not open a FileChannel that could disturb an existing OS lock.
        return regularOrMissing(a)&&regularOrMissing(b)&&Files.isSameFile(a,b);
    }
    private static Lease acquire(Path path)throws IOException {
        synchronized(REGISTRY_LOCK) {
            Path absolute=Objects.requireNonNull(path).toAbsolutePath();
            Path name=absolute.getFileName();
            if(name==null||name.toString().equals(".")||name.toString().equals(".."))
                throw new IOException("store must have a file name");
            Files.createDirectories(absolute.getParent());
            Path file=absolute.getParent().toRealPath().resolve(name);
            Path lockFile=file.resolveSibling(name+".lock");
            regularOrMissing(file);regularOrMissing(lockFile);
            if(sameExisting(file,lockFile))throw new IOException("store and lock must be distinct files");
            for(Lease held:ACTIVE) {
                if(file.equals(held.file())||lockFile.equals(held.lockFile())
                    ||file.equals(held.lockFile())||lockFile.equals(held.file())
                    ||sameExisting(file,held.file())||sameExisting(lockFile,held.lockFile())
                    ||sameExisting(file,held.lockFile())||sameExisting(lockFile,held.file()))
                    throw new IOException("another writer in this JVM owns store");
            }
            FileChannel channel=FileChannel.open(lockFile,StandardOpenOption.CREATE,
                    StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);
            try {
                FileLock lock=channel.tryLock();
                if(lock==null)throw new IOException("another process owns store");
                Lease lease=new Lease(file,lockFile,channel,lock);
                ACTIVE.add(lease);
                return lease;
            }catch(IOException|RuntimeException|Error e){cleanup(e,channel::close);throw e;}
        }
    }
    public DurableFile(Path path)throws IOException {lease=acquire(path);file=lease.file();}
    public synchronized Object read()throws IOException {
        if(poisoned||closed)throw new IOException("store unavailable");
        return Files.exists(file)?StrictJson.read(file):null;
    }
    public synchronized void save(Object data)throws IOException {
        if(poisoned||closed)throw new IOException("store unavailable; restart and inspect");
        byte[] bytes=StrictJson.write(data).getBytes(StandardCharsets.UTF_8);
        if(bytes.length>StrictJson.MAX_BYTES)throw new IOException("snapshot size limit");
        Path temp=Files.createTempFile(file.getParent(),"snapshot-",".tmp");Throwable primary=null;
        try {
            try(FileChannel c=FileChannel.open(temp,StandardOpenOption.WRITE)){ByteBuffer b=ByteBuffer.wrap(bytes);while(b.hasRemaining())c.write(b);c.force(true);}
            // Do not silently fall back to a non-atomic replacement.
            Files.move(temp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
        }catch(IOException|RuntimeException|Error e){primary=e;poisoned=true;throw e;}
        finally {
            try{cleanup(primary,()->Files.deleteIfExists(temp));}
            catch(IOException|RuntimeException|Error e){poisoned=true;throw e;}
        }
    }
    public synchronized void close()throws IOException {
        if(closed&&!lease.channel().isOpen())return;
        closed=true;
        // Do not remove the in-JVM reservation until the old channel is actually closed.
        synchronized(REGISTRY_LOCK) {
            Throwable primary=null;
            try {
                try{if(lease.lock().isValid())lease.lock().release();}
                catch(IOException|RuntimeException|Error e){primary=e;throw e;}
                finally{cleanup(primary,lease.channel()::close);}
            }finally {
                if(!lease.channel().isOpen())ACTIVE.remove(lease);
            }
        }
    }
}

import com.sun.net.httpserver.*;
import java.io.*;
import java.math.BigDecimal;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.LongSupplier;

/** Local trusted demo: one durable coordinator, multiple independent JVM workers. */
public final class ScriptService {
    static final int CAPACITY=128, MAX_ATTEMPTS=3;
    static final long LEASE_MILLIS=1000;
    static final class Conflict extends RuntimeException {
        private static final long serialVersionUID=1L;
        Conflict(String text){super(text);}
    }
    record Job(String id,String request,String template,Object input,String state,String owner,
               long epoch,int attempts,long until,long deadline,Object output) {
        Map<String,Object> json(){Map<String,Object> m=new TreeMap<>();
            m.put("id",id);m.put("request",request);m.put("template",template);m.put("input",StrictJson.parse(StrictJson.write(input)));
            m.put("state",state);m.put("owner",owner);m.put("epoch",epoch);m.put("attempts",attempts);
            m.put("until",until);m.put("deadline",deadline);m.put("output",StrictJson.parse(StrictJson.write(output)));return m;}
        Job changed(String state,String owner,long epoch,int attempts,long until,Object output){return new Job(id,request,template,input,state,owner,epoch,attempts,until,deadline,output);}
        static Job from(Object o){Map<String,Object> m=StrictJson.object(o);
            StrictJson.fields(m,"id","request","template","input","state","owner","epoch","attempts","until","deadline","output");
            Job j=new Job(StrictJson.id(StrictJson.str(m,"id")),StrictJson.str(m,"request"),StrictJson.str(m,"template"),m.get("input"),
                    StrictJson.str(m,"state"),StrictJson.str(m,"owner"),StrictJson.integer(m,"epoch"),Math.toIntExact(StrictJson.integer(m,"attempts")),
                    StrictJson.integer(m,"until"),StrictJson.integer(m,"deadline"),m.get("output"));
            validateInput(j.template,j.input);
            if(!Set.of("QUEUED","RUNNING","SUCCEEDED","FAILED").contains(j.state)||j.epoch<0||j.attempts<0||j.attempts>MAX_ATTEMPTS||j.until<0||j.deadline<0)
                throw new IllegalArgumentException("invalid snapshot job");
            if(!j.owner.isEmpty())StrictJson.id(j.owner);
            Map<String,Object> original=StrictJson.object(StrictJson.parse(j.request));
            StrictJson.fields(original,"id","template","input","ttlMillis");
            long ttl=StrictJson.integer(original,"ttlMillis");
            if(!j.id.equals(original.get("id"))||!j.template.equals(original.get("template"))||
               !StrictJson.write(j.input).equals(StrictJson.write(original.get("input")))||ttl<100||ttl>60000||
               !j.request.equals(StrictJson.write(original))||j.epoch!=j.attempts||j.until>j.deadline)
                throw new IllegalArgumentException("inconsistent snapshot");
            if((j.state.equals("RUNNING")||j.state.equals("SUCCEEDED"))&&(j.owner.isEmpty()||j.epoch==0))
                throw new IllegalArgumentException("missing lease identity");
            if(j.state.equals("SUCCEEDED")&&!StrictJson.write(j.output).equals(StrictJson.write(execute(j.template,j.input))))
                throw new IllegalArgumentException("invalid saved result");
            return j;
        }
    }
    static void validateInput(String template,Object input) {
        switch(template) {
            case "upper-v1" -> {if(!(input instanceof String s)||s.getBytes(StandardCharsets.UTF_8).length>512)throw new IllegalArgumentException("upper-v1 string <=512 bytes");}
            case "sum-v1" -> {
                if(!(input instanceof List<?> xs)||xs.size()>256)throw new IllegalArgumentException("sum-v1 array <=256");
                for(Object x:xs){if(!(x instanceof BigDecimal n))throw new IllegalArgumentException("integer array required");
                    long v;try{v=n.longValueExact();}catch(ArithmeticException e){throw new IllegalArgumentException("integer range");}
                    if(v < -1_000_000_000L||v>1_000_000_000L)throw new IllegalArgumentException("integer range");}
            }
            default -> throw new IllegalArgumentException("unknown template; executable text is not accepted");
        }
    }
    static Object execute(String template,Object input) {
        validateInput(template,input);
        if(template.equals("upper-v1"))return ((String)input).toUpperCase(Locale.ROOT);
        long sum=0;for(Object x:(List<?>)input)sum=Math.addExact(sum,((BigDecimal)x).longValueExact());
        return BigDecimal.valueOf(sum);
